// Extract email details from security alerts
const alerts = $input.first().json.value || [];
const emailAlerts = [];

for (const alert of alerts) {
  // Find email evidence in alert
  const emailEvidence = alert.evidence?.find(
    e => e['@odata.type'] === '#microsoft.graph.security.emailEvidence'
  );

  if (emailEvidence) {
    emailAlerts.push({
      alertId: alert.id,
      severity: alert.severity,
      subject: emailEvidence.subject || 'N/A',
      sender: emailEvidence.sender?.emailAddress || 'Unknown',
      recipient: emailEvidence.recipient?.emailAddress || 'Unknown',
      bodyPreview: emailEvidence.bodyPreview || '',
      urls: emailEvidence.urls || [],
      attachments: emailEvidence.attachments?.map(a => a.fileName) || [],
      receivedDateTime: emailEvidence.receivedDateTime,
      networkMessageId: emailEvidence.networkMessageId
    });
  }
}

return emailAlerts.map(e => ({json: e}));

// Prepare LLM analysis prompt
const email = $input.first().json;

const prompt = `Analyze this email for phishing indicators:

**Email Details:**
- Subject: ${email.subject}
- Sender: ${email.sender}
- Recipient: ${email.recipient}
- Body Preview: ${email.bodyPreview}
- URLs: ${email.urls.join(', ') || 'None'}
- Attachments: ${email.attachments.join(', ') || 'None'}

**Analysis Instructions:**
Evaluate for phishing based on:
1. Sender authenticity (domain spoofing, typosquatting)
2. Urgency or pressure tactics
3. Suspicious links or redirects
4. Grammar and spelling errors
5. Request for sensitive information
6. Unexpected attachments

**Required Response Format (JSON only):**
{
  "isPhishing": true/false,
  "confidence": 0-100,
  "severity": "low/medium/high/critical",
  "indicators": ["list of specific indicators found"],
  "reasoning": "detailed explanation of analysis",
  "recommendation": "quarantine/allow/review"
}

Respond with ONLY the JSON object, no additional text.`;

return [{
  json: {
    prompt: prompt,
    emailData: email
  }
}];

// Universal LLM response parser
// Works with OpenAI, Claude, Gemini, Ollama, and other LLM providers

const response = $input.first().json;
const emailData = $node['Prepare LLM Prompt'].json.emailData;

function extractJSON(llmResponse) {
  let text;

  // Handle different LLM response formats
  if (llmResponse.choices?.[0]?.message?.content) {
    // OpenAI format
    text = llmResponse.choices[0].message.content;
  } else if (llmResponse.content?.[0]?.text) {
    // Claude format
    text = llmResponse.content[0].text;
  } else if (llmResponse.candidates?.[0]?.content?.parts?.[0]?.text) {
    // Gemini format
    text = llmResponse.candidates[0].content.parts[0].text;
  } else if (llmResponse.response) {
    // Ollama format
    text = llmResponse.response;
  } else {
    // Fallback
    text = llmResponse.text || JSON.stringify(llmResponse);
  }

  // Clean markdown code blocks
  text = text.replace(/```json\n?|```\n?/g, '').trim();

  // Extract JSON object
  const jsonMatch = text.match(/\{[\s\S]*\}/);
  const jsonText = jsonMatch ? jsonMatch[0] : text;

  return JSON.parse(jsonText);
}

try {
  const analysis = extractJSON(response);

  return [{
    json: {
      alertId: emailData.alertId,
      email: emailData,
      aiAnalysis: analysis,
      isPhishing: analysis.isPhishing,
      confidence: analysis.confidence,
      severity: analysis.severity,
      indicators: analysis.indicators,
      reasoning: analysis.reasoning,
      recommendation: analysis.recommendation,
      timestamp: new Date().toISOString()
    }
  }];
} catch (error) {
  // Fallback for parsing errors
  return [{
    json: {
      alertId: emailData.alertId,
      email: emailData,
      aiAnalysis: { error: error.message },
      isPhishing: false,
      confidence: 0,
      severity: 'low',
      recommendation: 'manual_review',
      reasoning: `AI analysis failed: ${error.message}`,
      timestamp: new Date().toISOString()
    }
  }];
}

// Format phishing detection alert
const data = $input.first().json;
const analysis = data.aiAnalysis;
const email = data.email;

let message = `🎣 *AI Phishing Detection*\n\n`;
message += `*Email Details:*\n`;
message += `• Subject: ${email.subject}\n`;
message += `• Sender: ${email.sender}\n`;
message += `• Recipient: ${email.recipient}\n\n`;

message += `*AI Analysis:*\n`;
message += `• Phishing: ${data.isPhishing ? '✅ YES' : '❌ NO'}\n`;
message += `• Confidence: ${data.confidence}%\n`;
message += `• Severity: ${data.severity.toUpperCase()}\n`;
message += `• Recommendation: ${data.recommendation.toUpperCase()}\n\n`;

if (analysis.indicators && analysis.indicators.length > 0) {
  message += `*Indicators Found:*\n`;
  analysis.indicators.forEach(indicator => {
    message += `• ${indicator}\n`;
  });
  message += `\n`;
}

message += `*AI Reasoning:*\n${analysis.reasoning}\n\n`;

if (data.confidence >= $node['Set Config'].json.confidenceThreshold && data.isPhishing) {
  message += `⚠️ *Action Taken:* Email quarantined automatically\n`;
} else {
  message += `📋 *Action Required:* Manual review recommended\n`;
}

message += `\nTimestamp: ${data.timestamp}`;

return [{
  json: {
    channel: '#security-alerts',
    text: message,
    blocks: [
      {
        type: 'header',
        text: {
          type: 'plain_text',
          text: '🎣 AI Phishing Detection',
          emoji: true
        }
      },
      {
        type: 'section',
        text: {
          type: 'mrkdwn',
          text: message
        }
      }
    ]
  }
}];
